updates={}
for r in rows:
 if r['id'] in done or r['id'] in partial:
  r['status']='محلي' if r['id'] in done else 'جزئي'
  r['finding']=(done|partial)[r['id']]
  r['evidence']='operations-engine.js؛ workflow-engine.js؛ operations-ui.js؛ workflow-ui.js؛ test-operations.cjs؛ test-workflow.cjs؛ test-workflow-ui.cjs؛ test-xlsx-reader.cjs'
  r['confirmed_gap']=r['status']=='جزئي'
  updates[r['id']]={k:r[k] for k in ['status','finding','evidence','confirmed_gap']}
(b/'implementation-updates.json').write_text(json.dumps(updates,ensure_ascii=False,indent=2),encoding='utf-8')
(b/'requirements-audit.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
with (b/'requirements-audit.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f);w.writerow(['الرقم','القسم','المتطلب','المصدر','الحالة','الصفحة','الدليل','النتيجة'])
 for r in rows:w.writerow([r[k] for k in ['id','module','requirement','source','status','page','evidence','finding']])
builder=b/'build-audit.py';text=builder.read_text(encoding='utf-8');needle="jsonpath=base/'requirements-audit.json'"
if 'implementation-updates.json' not in text:
 text=text.replace(needle,"updates_path=base/'implementation-updates.json'\nif updates_path.exists():\n    updates=json.loads(updates_path.read_text(encoding='utf-8'))\n    for row in rows: row.update(updates.get(row['id'],{}))\n"+needle)
 builder.write_text(text,encoding='utf-8')
renderer=b/'render-report.py';text=renderer.read_text(encoding='utf-8')
text=text.replace('لم تُعدل بياناتك أو وظائف النظام أثناء المراجعة.','أُجريت تعديلات على وظائف الواجهة المحلية بعد المراجعة، واختبرت ببيانات معزولة دون تعديل بياناتك المحفوظة في المتصفح.')
text=re.sub(r'<section id="findings">.*?</section>', '<section id="findings"><h2>ما تغير في النظام</h2><p>أضيفت محافظ الخدمات والفوترة عند التحميل، طلبات التمويل والحجز والعكس ومنع التكرار، استيراد Excel والملفات المتعددة، تخصيص الفئات والحدود، الحجز قبل الإصدار واستثناء الطباعة، والتالف والتعويض والمطابقة والتصدير المعتمد والتشفير.</p><p><a href="../masal.html">فتح لوحة التحكم المعدلة</a> · <a href="implementation-notes.md">التغييرات والاختبارات والحدود المتبقية</a></p><p class="note">التعديل لا يعني اكتمال كل بند: ما زالت المصادقة الحساسة والاستعادة والجلسات والترجمات الشاملة وبعض الربط تحتاج استكمالًا. الجدول يحددها كجزئية أو بحاجة ربط، ولا يحوّلها إلى إنجاز بمجرد وجود حقل.</p></section>',text,flags=re.S)
text=re.sub(r'<section><h2>ما ثبت أنه يعمل محليًا</h2>.*?</section>', '<section><h2>التحقق بعد التعديل</h2><p>اجتازت دورات التمويل والحجز والتسوية والاستيراد والإصدار والطباعة والتالف اختبارات المحرك والواجهة، مع اختبار ملف Excel فعلي وكلمة تشفير صحيحة وخاطئة، وبقاء تغيير سعر المدير مباشرًا وإيقاف فروع الوكيل مقيدًا بشجرته.</p><p>النتائج السابقة في verified-gaps.json تخص النسخة قبل الإصلاح. نتائج التنفيذ الحديثة موضحة في <a href="implementation-notes.md">سجل التعديلات</a>. اختبارات الأنظمة الخارجية غير ممكنة دون توفير الربط.</p></section>',text,flags=re.S)
renderer.write_text(text,encoding='utf-8')
